#include "statuspanel.h"

#include <QLabel>
#include <QVBoxLayout>

#include "downloader.h"

StatusPanel::StatusPanel(Downloader *downloader, QWidget *parent)
    : QWidget(parent), m_label(new QLabel(this))
{
    auto *layout = new QVBoxLayout(this);
    layout->addWidget(m_label);

    connect(downloader, &Downloader::progressChanged, [this](int percent) {
        m_label->setText(QStringLiteral("%1%").arg(percent));
    });
}
